package com.lqq.supportflow.conversation.application;
import com.lqq.supportflow.conversation.GenerationRequestedEvent; import com.lqq.supportflow.conversation.HandoffRequiredEvent; import com.lqq.supportflow.conversation.domain.*; import org.springframework.context.ApplicationEventPublisher; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SubmitCustomerMessageService { private final ConversationPort conversations; private final GenerationEventStore events; private final HandoffPolicy handoff; private final ApplicationEventPublisher publisher; public SubmitCustomerMessageService(ConversationPort conversations,GenerationEventStore events,HandoffPolicy handoff,ApplicationEventPublisher publisher){this.conversations=conversations;this.events=events;this.handoff=handoff;this.publisher=publisher;} @Transactional public Generation submit(Long tenantId,Long customerId,Long conversationId,String content,String idempotencyKey){if(!conversations.belongsTo(tenantId,customerId,conversationId))throw new IllegalArgumentException("conversation does not belong to customer");Generation generation=conversations.submit(tenantId,conversationId,content,idempotencyKey);if(handoff.requiresHandoff(content)){generation=conversations.requireHandoff(tenantId,conversationId,generation.id());events.appendIfAbsent(generation.id(),"handoff.required","{\"status\":\"HANDOFF_REQUIRED\"}");publisher.publishEvent(new HandoffRequiredEvent(tenantId,customerId,conversationId,generation.id(),"customer request requires an agent"));return generation;}events.appendIfAbsent(generation.id(),"generation.queued","{\"status\":\"QUEUED\"}");publisher.publishEvent(new GenerationRequestedEvent(tenantId,customerId,conversationId,generation.id(),content));return generation;}}
